// Guards the edge function bundle size fix (see CLAUDE.md, "Edge function
// bundle size", and supabase/functions/_vendor/README.md).
//
// mcp and mcp-public are regenerated by the @lovable.dev/mcp-js Vite plugin
// and import "npm:@lovable.dev/mcp-js@<version>". If Supabase's deploy ever
// resolves that npm package, it also installs esbuild and vite (with rolldown
// and lightningcss native binaries), the bundle reaches about 100 MB and every
// function deploy fails with 413. supabase/functions/deno.json maps each such
// specifier to a vendored copy of the runtime files instead. A plugin upgrade
// that changes the version string would silently bypass the map, so these
// tests fail until the new version is vendored and mapped.
import { existsSync, readdirSync, readFileSync } from "node:fs";
import { dirname, join, resolve } from "node:path";
import { describe, expect, it } from "vitest";

const FUNCTIONS_DIR = resolve(__dirname, "../../../../supabase/functions");
const SPECIFIER = /["']npm:@lovable\.dev\/mcp-js@[^"']+["']/g;

const denoConfig = JSON.parse(
  readFileSync(join(FUNCTIONS_DIR, "deno.json"), "utf8"),
) as { imports?: Record<string, string> };
const importMap = denoConfig.imports ?? {};

const functionSources = readdirSync(FUNCTIONS_DIR, { withFileTypes: true })
  .filter(
    (d) =>
      d.isDirectory() && !d.name.startsWith("_") && d.name !== "node_modules",
  )
  .flatMap((d) =>
    readdirSync(join(FUNCTIONS_DIR, d.name))
      .filter((f) => /\.(ts|tsx|js|mjs)$/.test(f))
      .map((f) => join(FUNCTIONS_DIR, d.name, f)),
  );

const usedSpecifiers = [
  ...new Set(
    functionSources.flatMap((file) =>
      [...readFileSync(file, "utf8").matchAll(SPECIFIER)].map((m) =>
        m[0].slice(1, -1),
      ),
    ),
  ),
].sort();

describe("vendored @lovable.dev/mcp-js", () => {
  it("is still imported by the mcp functions (the guard is not vacuous)", () => {
    expect(usedSpecifiers.length).toBeGreaterThan(0);
  });

  it("maps every mcp-js specifier a function imports to a vendored file", () => {
    const unmapped = usedSpecifiers.filter((s) => !(s in importMap));
    expect(unmapped).toEqual([]);
  });

  it("points every mcp-js mapping at a file that exists under _vendor", () => {
    const broken = Object.entries(importMap)
      .filter(([key]) => key.startsWith("npm:@lovable.dev/mcp-js@"))
      .filter(([, target]) => {
        const path = resolve(FUNCTIONS_DIR, target);
        return !target.startsWith("./_vendor/") || !existsSync(path);
      })
      .map(([key, target]) => `${key} -> ${target}`);
    expect(broken).toEqual([]);
  });

  it("never imports esbuild or vite from the vendored runtime files", () => {
    const vendorRoots = Object.entries(importMap)
      .filter(([key]) => key.startsWith("npm:@lovable.dev/mcp-js@"))
      .map(([, target]) => dirname(resolve(FUNCTIONS_DIR, target)));
    const offenders: string[] = [];
    const walk = (dir: string) => {
      for (const entry of readdirSync(dir, { withFileTypes: true })) {
        const path = join(dir, entry.name);
        if (entry.isDirectory()) walk(path);
        else if (
          /\.js$/.test(entry.name) &&
          /from\s*["'](esbuild|vite)(\/[^"']*)?["']|import\(\s*["'](esbuild|vite)/.test(
            readFileSync(path, "utf8"),
          )
        )
          offenders.push(path);
      }
    };
    for (const root of new Set(vendorRoots)) walk(root);
    expect(offenders).toEqual([]);
  });
});
